#include <chrono>
#include <vector>
#include <fstream>
#include <string>
#include <algorithm>
#define main original_nonzero_main
#include "../nonzero-cuda/main.cu"
#undef main
int main(){const int nr=256,nc=256,n=nr*nc,r=5;std::vector<int>input(n);std::vector<int64_t>rows,cols;for(int i=0;i<n;i++){input[i]=(i*37+11)%5==0?0:(i%2?-1:1);if(input[i]){rows.push_back(i/nc);cols.push_back(i%nc);}}int64_t expected_nz=rows.size();std::vector<int64_t>expected(1,expected_nz);expected.insert(expected.end(),rows.begin(),rows.end());expected.insert(expected.end(),cols.begin(),cols.end());int *din;int64_t*out,*count;cudaMalloc(&din,n*4);cudaMalloc(&out,2*n*8);cudaMalloc(&count,8);cudaMemcpy(din,input.data(),n*4,cudaMemcpyHostToDevice);cub::TransformInputIterator<bool,NonZero<int>,int*>flags(din,NonZero<int>{});cub::CountingInputIterator<int64_t>indices(0);size_t bytes_reduce=0,bytes_select=0;cub::DeviceReduce::Sum(nullptr,bytes_reduce,flags,count,n);cub::DeviceSelect::Flagged(nullptr,bytes_select,indices,flags,out,count,n);void*tmp_reduce,*tmp_select;cudaMalloc(&tmp_reduce,bytes_reduce);cudaMalloc(&tmp_select,bytes_select);TensorDims<int64_t>dims;dims.sizes[0]=nr;dims.sizes[1]=nc;int64_t nz=0;auto launch=[&](){cub::DeviceReduce::Sum(tmp_reduce,bytes_reduce,flags,count,n);cudaMemcpy(&nz,count,8,cudaMemcpyDeviceToHost);cub::DeviceSelect::Flagged(tmp_select,bytes_select,indices,flags,out,count,n);write_indices<int64_t><<<(nz+255)/256,256>>>(out,dims,2,nz);};launch();cudaDeviceSynchronize();bool all=true;for(int trial=1;trial<=5;trial++){auto start=std::chrono::steady_clock::now();for(int j=0;j<r;j++)launch();auto error=cudaDeviceSynchronize();double secs=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/r;bool ok=error==cudaSuccess&&nz>=0&&nz<=n;std::vector<int64_t>got(2*std::max<int64_t>(0,std::min<int64_t>(n,nz))+1);got[0]=nz;cudaMemcpy(got.data()+1,out,(got.size()-1)*8,cudaMemcpyDeviceToHost);ok &=got==expected;all &=ok;std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/output_trial"+std::to_string(trial)+".bin";std::ofstream(path,std::ios::binary).write((char*)got.data(),got.size()*8);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":0,\"max_rel_error\":0,\"timing_region\":\"kernel_launch_loop_per_internal_repeat\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,secs,ok?"true":"false",got.size(),r,path.c_str(),got.size());}puts(all?"PASS":"FAIL");return all?0:1;}
